create table public.stable_brand_privileges(stable_id uuid primary key references stables(id),granted boolean not null default true,permanent boolean not null default false,reason text not null default '',granted_by uuid references stables(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.stable_brands(id uuid primary key default gen_random_uuid(),stable_id uuid not null unique references stables(id),code text not null,normalized_code text generated always as(upper(code))stored unique,mark_url text,mark_version integer not null default 1,active boolean not null default true,reserved boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(code~'^[A-Za-z0-9]{2,4}$'));
create table public.stable_brand_audit(id uuid primary key default gen_random_uuid(),brand_id uuid references stable_brands(id),horse_id uuid references horses(id),stable_id uuid references stables(id),actor_id uuid references stables(id),action text not null,old_values jsonb not null default '{}',new_values jsonb not null default '{}',reason text not null default '',created_at timestamptz not null default now());
alter table horses add column if not exists horse_brand_id uuid references stable_brands(id),add column if not exists brand_code_at_assignment text,add column if not exists brand_mark_at_assignment text,add column if not exists brand_mark_version integer,add column if not exists branded_by_account bigint,add column if not exists brand_origin text,add column if not exists brand_assigned_at timestamptz,add column if not exists breeder_stable_id uuid references stables(id),add column if not exists breeder_name_at_birth text,add column if not exists breeder_account_at_birth bigint;
alter table stable_brand_privileges enable row level security;alter table stable_brands enable row level security;alter table stable_brand_audit enable row level security;
create policy "brand privileges visible to owner" on stable_brand_privileges for select using(stable_id=auth.uid());create policy "brands publicly visible" on stable_brands for select using(true);create policy "own brand audit readable" on stable_brand_audit for select using(stable_id=auth.uid()or exists(select 1 from stables where id=auth.uid()and is_admin));
create or replace function public.has_brand_privilege(p_stable uuid,p_at timestamptz default now())returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from stables where id=p_stable and account_number=1)or exists(select 1 from stable_brand_privileges where stable_id=p_stable and granted)or is_active_subscriber(p_stable,p_at)$$;
create or replace function public.assign_horse_brand(p_horse uuid,p_stable uuid,p_origin text)returns boolean language plpgsql security definer set search_path=public as $$declare b stable_brands;s stables;begin select * into b from stable_brands where stable_id=p_stable and active;if not found or not has_brand_privilege(p_stable)then return false;end if;select * into s from stables where id=p_stable;update horses set horse_brand_id=b.id,brand_code_at_assignment=b.code,brand_mark_at_assignment=b.mark_url,brand_mark_version=b.mark_version,branded_by_account=s.account_number,brand_origin=p_origin,brand_assigned_at=now(),breeder_stable_id=case when p_origin='Foal Birth'then s.id else breeder_stable_id end,breeder_name_at_birth=case when p_origin='Foal Birth'then s.name else breeder_name_at_birth end,breeder_account_at_birth=case when p_origin='Foal Birth'then s.account_number else breeder_account_at_birth end where id=p_horse and horse_brand_id is null;if found then insert into stable_brand_audit(brand_id,horse_id,stable_id,actor_id,action,new_values,reason)values(b.id,p_horse,p_stable,auth.uid(),'horse_brand_assigned',jsonb_build_object('code',b.code,'mark',b.mark_url,'origin',p_origin),p_origin);return true;end if;return false;end$$;
create or replace function public.brand_foundation_purchase()returns trigger language plpgsql security definer set search_path=public as $$begin if new.status='sold'and old.status='active'and new.sold_to is not null then perform assign_horse_brand(new.horse_id,new.sold_to,'Foundation Purchase');end if;return new;end$$;create trigger assign_foundation_brand after update of status on store_inventory for each row execute function brand_foundation_purchase();
create or replace function public.brand_new_foal()returns trigger language plpgsql security definer set search_path=public as $$declare dam_owner uuid;s stables;begin if new.origin='Bred'and new.dam_id is not null then select owner_id into dam_owner from horses where id=new.dam_id;select * into s from stables where id=dam_owner;update horses set breeder_stable_id=dam_owner,breeder_name_at_birth=s.name,breeder_account_at_birth=s.account_number where id=new.id;perform assign_horse_brand(new.id,dam_owner,'Foal Birth');end if;return new;end$$;create trigger assign_foal_brand after insert on horses for each row execute function brand_new_foal();
create or replace function public.get_my_stable_brand()returns jsonb language plpgsql stable security definer set search_path=public as $$declare b stable_brands;begin select * into b from stable_brands where stable_id=auth.uid();return jsonb_build_object('eligible',has_brand_privilege(auth.uid()),'brand',case when b.id is null then null else to_jsonb(b)end);end$$;
create or replace function public.save_my_stable_brand(p_code text,p_mark_url text default null)returns stable_brands language plpgsql security definer set search_path=public as $$declare b stable_brands;assigned bigint;begin if not has_brand_privilege(auth.uid())then raise exception 'Stable Brand requires an active subscription or Brand Privilege';end if;p_code:=upper(trim(p_code));if p_code!~'^[A-Z0-9]{2,4}$'then raise exception 'Brand Code must contain 2–4 letters or numbers';end if;select count(*)into assigned from horses where horse_brand_id=(select id from stable_brands where stable_id=auth.uid());if assigned>0 and exists(select 1 from stable_brands where stable_id=auth.uid()and normalized_code<>p_code)then raise exception 'Contact an Owner/Admin to change a Brand Code already used on horses';end if;insert into stable_brands(stable_id,code,mark_url)values(auth.uid(),p_code,nullif(p_mark_url,''))on conflict(stable_id)do update set code=excluded.code,mark_url=excluded.mark_url,mark_version=case when stable_brands.mark_url is distinct from excluded.mark_url then stable_brands.mark_version+1 else stable_brands.mark_version end,active=true,updated_at=now()returning * into b;insert into stable_brand_audit(brand_id,stable_id,actor_id,action,new_values)values(b.id,auth.uid(),auth.uid(),'brand_saved',jsonb_build_object('code',b.code,'mark',b.mark_url,'version',b.mark_version));return b;exception when unique_violation then raise exception 'That Brand Code is already reserved';end$$;
create or replace function public.admin_set_brand_privilege(p_stable uuid,p_granted boolean,p_permanent boolean,p_reason text)returns void language plpgsql security definer set search_path=public as $$begin perform require_super_admin();insert into stable_brand_privileges(stable_id,granted,permanent,reason,granted_by)values(p_stable,p_granted,p_permanent,left(p_reason,300),auth.uid())on conflict(stable_id)do update set granted=excluded.granted,permanent=excluded.permanent,reason=excluded.reason,granted_by=auth.uid(),updated_at=now();insert into stable_brand_audit(stable_id,actor_id,action,new_values,reason)values(p_stable,auth.uid(),'brand_privilege_changed',jsonb_build_object('granted',p_granted,'permanent',p_permanent),left(p_reason,300));end$$;
insert into stable_brand_privileges(stable_id,granted,permanent,reason)select id,true,true,'Permanent Owner #1 Brand Privilege'from stables where account_number=1 on conflict(stable_id)do update set granted=true,permanent=true;
insert into stable_brands(stable_id,code,active,reserved)select id,'TFR',true,true from stables where account_number=1 on conflict(stable_id)do update set code='TFR',active=true,reserved=true;
revoke all on function has_brand_privilege(uuid,timestamptz),assign_horse_brand(uuid,uuid,text),get_my_stable_brand(),save_my_stable_brand(text,text),admin_set_brand_privilege(uuid,boolean,boolean,text)from public;grant execute on function get_my_stable_brand(),save_my_stable_brand(text,text)to authenticated;grant execute on function admin_set_brand_privilege(uuid,boolean,boolean,text)to authenticated;
